/**
 * logoPdfHelper.js
 * Velocity Lab - Universal Brand Logo Exporter for PDFs and Canvas Video Exports.
 */

export const LOGO_ASPECT_RATIO = 1201 / 351;

export const VELOCITY_LAB_LOGO_DATA_URIS = {
  light_orange: "data:image/png;base64,",
  dark_orange: "data:image/png;base64,",
  light_green: "data:image/png;base64,",
  dark_green: "data:image/png;base64,",
};

const preloadedImages = {
  light_orange: null,
  dark_orange: null,
  light_green: null,
  dark_green: null,
};

function initPreloadedImages() {
  if (typeof window === 'undefined') return;
  for (const [key, uri] of Object.entries(VELOCITY_LAB_LOGO_DATA_URIS)) {
    if (!preloadedImages[key]) {
      const img = new Image();
      img.src = uri;
      preloadedImages[key] = img;
    }
  }
}

if (typeof window !== 'undefined') {
  initPreloadedImages();
}

export function resolveBrandTheme(colorTheme, isDark) {
  let resolvedColor = colorTheme;
  if (!resolvedColor && typeof window !== 'undefined') {
    resolvedColor = localStorage.getItem('sprintgate_color_theme') || 'orange';
  }
  const isGreen = resolvedColor === 'emerald' || resolvedColor === 'green' || resolvedColor === 'volt';
  
  let resolvedDark = isDark;
  if (resolvedDark === undefined && typeof window !== 'undefined') {
    resolvedDark = document.documentElement.classList.contains('dark') || 
                   localStorage.getItem('sprintgate_theme') === 'dark';
  }

  const key = `${resolvedDark ? 'dark' : 'light'}_${isGreen ? 'green' : 'orange'}`;
  return {
    key,
    isDark: !!resolvedDark,
    isGreen,
    dataUri: VELOCITY_LAB_LOGO_DATA_URIS[key] || VELOCITY_LAB_LOGO_DATA_URIS.dark_orange
  };
}

export function getLogoDataUri({ isDark = false, colorTheme = 'orange' } = {}) {
  const theme = resolveBrandTheme(colorTheme, isDark);
  return theme.dataUri;
}

export function addVelocityLabLogoToPdf(doc, {
  x = 14,
  y = 10,
  width = 46,
  height = null,
  isDark = false,
  colorTheme = null
} = {}) {
  if (!doc || typeof doc.addImage !== 'function') return null;

  const actualHeight = height || (width / LOGO_ASPECT_RATIO);
  const theme = resolveBrandTheme(colorTheme, isDark);

  try {
    doc.addImage(theme.dataUri, 'PNG', x, y, width, actualHeight);
  } catch (err) {
    console.warn('[logoPdfHelper] Failed to add logo image to PDF, falling back to text:', err);
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(16);
    doc.setTextColor(theme.isGreen ? 16 : 249, theme.isGreen ? 185 : 115, theme.isGreen ? 129 : 22);
    doc.text('VELOCITY LAB', x, y + actualHeight * 0.7);
  }

  return {
    x,
    y,
    width,
    height: actualHeight,
    nextY: y + actualHeight
  };
}

export function drawVelocityLabLogoOnCanvas(ctx, {
  x = 0,
  y = 0,
  width = 160,
  height = null,
  isDark = true,
  colorTheme = null
} = {}) {
  if (!ctx) return null;

  initPreloadedImages();
  const actualHeight = height || (width / LOGO_ASPECT_RATIO);
  const theme = resolveBrandTheme(colorTheme, isDark);
  let img = preloadedImages[theme.key];

  if (img && img.complete && img.naturalWidth > 0) {
    ctx.drawImage(img, x, y, width, actualHeight);
  } else {
    const fallbackImg = new Image();
    fallbackImg.src = theme.dataUri;
    if (fallbackImg.complete) {
      ctx.drawImage(fallbackImg, x, y, width, actualHeight);
    } else {
      fallbackImg.onload = () => {
        try { ctx.drawImage(fallbackImg, x, y, width, actualHeight); } catch(e) {}
      };
    }
  }

  return {
    x,
    y,
    width,
    height: actualHeight
  };
}

export default {
  LOGO_ASPECT_RATIO,
  VELOCITY_LAB_LOGO_DATA_URIS,
  resolveBrandTheme,
  getLogoDataUri,
  addVelocityLabLogoToPdf,
  drawVelocityLabLogoOnCanvas
};
